def priority(item: float, bins: np.ndarray) -> np.ndarray:
    residuals = bins - item
    return np.where(residuals >= 0, -np.tanh(residuals ** 3), -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    residuals = bins - item
    return np.where(residuals >= 0, 1.0 / (residuals + 1e-5), -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    return np.where(remaining >= 0, remaining, -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    return np.where(remaining >= 0, -np.exp(-(remaining ** 2)), -np.inf)
